// Then WAIT 20 (S:630) and VELTIME a=100 r=3.2 (S:631): 0.5 -> 3.2, +2.7/100 px/frame.
xformdef BALL2_WAIT20_ACCEL100 {
    @20 add_speed(0fx);         // S:630 WAIT 20
    @100 set_accel(0.027fx);    // S:631 VELTIME 100
    set_accel(0fx);
}

async sub girl_a04_at(ways: int, per_volley: int, gap: int) {
    wait(10);                           // S:613
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 10);       // S:616 etSprite(0,5,10)
    sh_ring(0, 0);                      // S:615 etAim(0,0): aimed fan
    sh_aim(0, 1);
    sh_count(0, ways, 1);               // S:617-626: 1/1/3/3 paths by rank
    sh_speed(0, 0.5fx, 0fx);            // S:628 etSpeed(0,0.5,1.0), M=1 -> 0.5
    sh_dist(0, -2fx);                   // S:629 ANIM a=1 retreat kept
    sh_xform(0, BALL2_WAIT20_ACCEL100); // S:629-631
    for outer in 0..10 {                // S:633 $A=10 -> 10 outer passes
        for inner in 0..per_volley {    // S:636 $B=5/10/10/10 by rank
            // S:639 RANDRAD then RANDF2*32; S:640 RANDF2*2deg. Source draw order kept.
            var off_ang: angle = rand(65536) as angle;
            var u: fx = (rand(65536)-32768) as fx / 32768;
            sh_offset_rad(0, off_ang, u * 32fx);
            var uj: fx = (rand(65536)-32768) as fx / 32768;
            var jitter: angle = (uj * 364fx) as int as angle;   // 2deg = 364 BAM
            sh_angle(0, jitter, 60deg);                         // S:640 1.0471976 rad
            sh_fire(0);                                         // S:641 etOn(0)
            wait(2);                                            // S:642
        }
        wait(gap);                      // S:645-653: Easy160 / Normal80 / Hard80 / Lunatic60
    }
}

async sub girl_a04(move_ang: angle, turn: angle) {
    set_invuln(65535);                  // training shell
    set_hurtbox(12fx);                  // S:596 setHurtbox(24,24): source circle radius 12
    set_hitbox(8fx);                    // S:597 setHitbox(16,16): source ordinary circle w*0.5
    var rank: int = global(GVAR_RANK);
    var ways: int = 1;
    var per_volley: int = 10;
    var gap: int = 80;
    if rank >= 2 { ways = 3; }          // S:617-626
    if rank == 0 { per_volley = 5; gap = 160; }   // S:636, S:645-653
    if rank == 3 { gap = 60; }
    move_vel(0, move_ang, 1.4fx, EASE_LINEAR);    // S:598 moveVel(1.1780972,1.4); mirrored copy
    spawn girl_a04_at(ways, per_volley, gap);     // S:599 async GirlA04_at
    wait(120);                          // S:600
    // S:601 moveVelTime(360,7,-0.017453292,0.0): mode7 adds -1deg/frame to heading, speed delta 0.
    var heading: angle = move_ang;
    for i in 0..360 {
        heading = heading + turn;       // left: -1deg/frame; mirrored right: +1deg/frame
        move_angle(0, heading, EASE_LINEAR);
        wait(1);
    }
    loop { wait(1000); }                // S:603-606
}

